        // 迭代

        ListNode* prev = nullptr; // 前一个结点
        ListNode* curr = head;    // 遍历
        ListNode* next = nullptr; // 存储下一个结点

        while (curr != nullptr) {
            next = curr->next; // 存储下一个结点
            curr->next = prev; // 反转当前
            prev = curr;       // 移动
            curr = next;       // 移动
        }
        return prev;
    }
};
```

## 234. 回文链表
这个题目能用到上面的解法，先用快慢指针找到中点，然后反转后面的链表，然后双指针从两边向中心靠近且比较：

```cpp
class Solution {
public:
    bool isPalindrome(ListNode* head) {
        if (head == nullptr || head->next == nullptr)
            return true;

        ListNode *slow = head, *fast = head, *prev = nullptr, *next = nullptr;


        while (fast != nullptr && fast->next != nullptr) {
            fast = fast->next->next;
            slow = slow->next;
        }

        while (slow != nullptr) {
            next = slow->next;
            slow->next = prev;
            prev = slow;
            slow = next;
        }

        ListNode* left = head;
        ListNode* right = prev;
        while (right != nullptr) {
            if (left->val != right->val)
                return false;
            left = left->next;
            right = right->next;
        }

        return true;
    }
};
```

