## 101. 对称二叉树
判断是否对称，检查 root->left->val == root->right->val，接着进行递归检查对称位置：

```cpp
class Solution {
public:
	// 传入对称位置的两个对称位置
    bool isMirror(TreeNode* left, TreeNode* right) {
        if (!left && !right)
            return true;
        if (!left || !right)
            return false;
        if (left->val != right->val)
            return false;
        return isMirror(left->left, right->right) &&
               isMirror(left->right, right->left);
    }
    bool isSymmetric(TreeNode* root) {
        if (!root)
            return true;
        return isMirror(root->left, root->right);
    }
};
```

## 543. 二叉树的直径
求二叉树的直径，就是在求当前节点左子树的深度和右子树的深度，两者一加，然后求最大值就可以了：

```cpp
class Solution {
private:
    int maxDiameter = 0;

    int maxDepth(TreeNode* node) {
        if (!node)
            return 0;
        int leftMax = maxDepth(node->left);
        int rightMax = maxDepth(node->right);

        maxDiameter = max(leftMax + rightMax, maxDiameter);
        return max(leftMax, rightMax) + 1;
    }

public:
    int diameterOfBinaryTree(TreeNode* root) {
        maxDepth(root); // 开始递归计算深度，并更新直径
        return maxDiameter;
    }
};
```

## 102. 二叉树的层序遍历
这个就是 bfs，直接利用队列：

```cpp
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        deque<TreeNode*> que; // 性能好
        if (!root)
            return {};
        vector<vector<int>> ans;
        vector<int> ansi;
        que.push_back(root);
        while (!que.empty()) {
            // 一次处理一层
            int levelSize = que.size();

            for (int i = 0; i < levelSize; i++) {
                TreeNode* temp = que.front();
                que.pop_front();
                ansi.push_back(temp->val);
                if (temp->left)
                    que.push_back(temp->left);
                if (temp->right)
                    que.push_back(temp->right);
            }
            ans.push_back(std::move(ansi));
        }
        return ans;
    }
};
```

## 108. 将有序数组转换为二叉搜索树
这道题的思路是，直接找数组的中间节点为根节点，这把数组分为两部分，然后递归创建二叉树：

```cpp
class Solution {
public:
    TreeNode* sortedArrayToBST(vector<int>& nums) {
        return createBST(nums, 0, nums.size() - 1);
    }

    TreeNode* createBST(const vector<int>& nums, int left, int right) {
        if (left > right) {
            return nullptr;
        }
        int mid = left + (right - left) / 2;
        TreeNode* node = new TreeNode(nums[mid]);
        node->left = createBST(nums, left, mid - 1);
        node->right = createBST(nums, mid + 1, right);

        return node;
    }
};
```

## 98. 验证二叉搜索树
依然是递归的思路：每次将当前节点的值作为验证左子树的最大值，作为验证右子树的最大值：

```cpp
class Solution {
public:
    bool isValidBST(TreeNode* root) {
        return isValidBSTHelper(root, LONG_MIN, LONG_MAX);
    }

private:
    bool isValidBSTHelper(TreeNode* node, long minVal, long maxVal) {
        if (!node)
            return true;
        if (node->val <= minVal || node->val >= maxVal)
            return false;

        return isValidBSTHelper(node->left, minVal, node->val) &&
               isValidBSTHelper(node->right, node->val, maxVal);
    }
};
```

## 230. 二叉搜索树中第K小的元素
这是搜索树，而搜索树的中序遍历顺序就是有序，因此可以中序遍历此树，然后将第 k 个值赋给变量 result ，然后返回：
```cpp
class Solution {
public:
    int kthSmallest(TreeNode* root, int k) {
        int count = 0;
        int result = 0;
        inorder(root, k, count, result);
        return result;
    }

private:
    void inorder(TreeNode* node, int k, int& count, int& result) {
        if (!node)
            return;
        // 遍历左子树
        inorder(node->left, k, count, result);
        // 访问当前节点
        ++count;
        if (count == k) {
            result = node->val;
            return;
        }
        // 遍历右子树
        inorder(node->right, k, count, result);
    }
};
```

