## 20. 有效的括号
利用栈：

```cpp
class Solution {
public:
    bool isValid(string s) {
        std::map<char, int> m = {{'(', -1}, {')', 1},  {'{', -2},
                                 {'}', 2},  {'[', -3}, {']', 3}};
        stack<char> st;
        for (auto c : s) {
            !st.empty() && m[st.top()] < 0 && m[st.top()] + m[c] == 0
                ? st.pop()
                : st.push(c);
        }
        return st.empty();
    }
};
```

## 155. 最小栈

核心思路是，要保证辅助栈的 top 永远是当前栈的最小值：

```cpp
class MinStack {
public:
    MinStack() { // 初始化时可以将一个极大值推入 min 栈作为哨兵值，简化代码逻辑
        min.push(INT_MAX);
    }

    void push(int val) {
        st.push(val);
        // 无论如何都将当前最小值推入min栈
        min.push(std::min(min.top(), val));
    }

    void pop() {
        st.pop();
        min.pop();
    }

    int top() { return st.top(); }

    int getMin() { return min.top(); }

private:
    stack<int> st;
    stack<int> min;
};

/**
