    std::string name = "SantaClausSantaClausSantaClausSantaClausSantaClausSantaClausSantaClausSantaClaus";
    ...
}
int main() {
    ...
    ...
    Widget w;
    w.setName("SantaClausSantaClausSantaClausSantaClaus");
 ...
}
```
