    let circle = Circle { radius: 5.0 };
    let rectangle = Rectangle { width: 4.0, height: 6.0 };

    println!("Circle Area: {}, Perimeter: {}", circle.area(), circle.perimeter());
    println!("Rectangle Area: {}, Perimeter: {}", rectangle.area(), rectangle.perimeter());
}
```

