the pointer cannot be relied upon anymore, and neither be free()d directly.*/
void strbuf_attach(struct strbuf* sb, void* str, size_t len, size_t alloc) {
    sb->alloc = alloc;
    sb->len = len;
    sb->buf = (char*)str;
}
