void strbuf_splice(struct strbuf* sb,
                   size_t pos,
                   size_t len,
                   const void* data,
                   size_t dlen) {
    if (dlen >= len)
        strbuf_grow(sb, dlen - len);
    memmove(sb->buf + pos + dlen, sb->buf + pos + len, sb->len - pos - len);
    /* it is better than memcpy()

    const char dest[] = "oldstring";
    memmove(&dest[1], &dest[2], 4); // odstrring
