}
// Part 2C
/*Strip whitespace from the front of a string.*/
void strbuf_ltrim(struct strbuf* sb) {
    char* b = sb->buf;
    while (sb->len > 0 && isspace(*b)) {
        b++;
        sb->len--;
    }
    memmove(sb->buf, b, sb->len);
    sb->buf[sb->len] = '\0';
}
/*Strip whitespace from the end of a string.*/
