    sb->buf[sb->len++] = ch;

    // big enough for the file
    sb->alloc <<= 13;
    sb->buf = (char*)realloc(sb->buf, sizeof(char) * (sb->alloc));
    while ((ch = fgetc(file)) != EOF) {
        sb->buf[sb->len] = ch;
        sb->len++;
    }
    sb->buf[sb->len] = '\0';
    return sb->len;
}

